CREATE TABLE IF NOT EXISTS `#__intercom_abandonments` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `draft_id` int unsigned NOT NULL, `revision` int unsigned NOT NULL, `lease_generation` int unsigned NOT NULL, `filter_id` int unsigned NOT NULL, `mailing_id` int unsigned NOT NULL, `account_id` varchar(20) NOT NULL, `group_id` int unsigned NOT NULL, `previous_state` varchar(24) NOT NULL, `actor_id` int unsigned NOT NULL, `reason` varchar(2000) NOT NULL, `state` varchar(24) NOT NULL, `baseline_verified` tinyint unsigned NOT NULL DEFAULT 0, `verified_by` int unsigned DEFAULT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `verified_at` datetime DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `draft_generation` (`draft_id`,`lease_generation`), KEY `filter_state` (`filter_id`,`state`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
